// Standalone inference helper (majority vote across all trees).
// teensy_final.ino defines its own classify()/predictTree() against the
// arrays above; this function is provided so the header is usable on its
// own in another sketch, without name collisions against that code.
static inline int rf_classify_standalone(const float feat[RF_NUM_FEATURES], float* confidence_out) {
  int votes[RF_NUM_CLASSES] = {0};
  for (int t = 0; t < RF_NUM_TREES; t++) {
    int idx = RF_TREE_ROOTS[t];
    while (RF_NODES[idx].feature != -1) {
      if (feat[RF_NODES[idx].feature] <= RF_NODES[idx].threshold)
        idx = RF_NODES[idx].left;
      else
        idx = RF_NODES[idx].right;
    }
    votes[RF_NODES[idx].leaf_class]++;
  }
  int best = 0;
  for (int c = 1; c < RF_NUM_CLASSES; c++) if (votes[c] > votes[best]) best = c;
  if (confidence_out) *confidence_out = (float)votes[best] / RF_NUM_TREES;
  return best;
}

